import { afterAll, beforeAll, expect, test } from 'bun:test';
import { chromium, type Browser, type Page } from 'playwright';
import { spawn, type ChildProcess } from 'node:child_process';
import { mkdirSync, openSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { feedExcerpt } from './feed-review-candidate/apps/web/features/feed/preview.ts';

const snapshot = resolve('.temp/feed-review-candidate');
const evidence = resolve('.temp/feed-review-evidence');
const origin = 'http://127.0.0.1:62837';
let server: ChildProcess;
let browser: Browser;
let browserPage: Page;
let release = () => {};
let injected = false;
let delayFresh = false;
const network: any[] = [];
const observations: any[] = [];
mkdirSync(evidence, { recursive: true });
const save = () => writeFileSync(`${evidence}/live-focus-confirmation-observations.json`, JSON.stringify({ network, observations }, null, 2));

beforeAll(async () => {
  server = spawn('task', ['--dir', snapshot, 'web:dev', '--', '--port', '62837'], {
    detached: true, stdio: ['ignore', openSync(`${evidence}/web-server.log`, 'a'), openSync(`${evidence}/web-server.log`, 'a')],
    env: { ...process.env, WRANGLER_SEND_METRICS: 'false' },
  });
  let ready = false;
  for (let attempt = 0; attempt < 150; attempt++) {
    try { const response = await fetch(`${origin}/favicon.ico`, { signal: AbortSignal.timeout(2000) }); if (response.status !== 503) { ready = true; break; } } catch {}
    await Bun.sleep(1000);
  }
  if (!ready) throw new Error('Candidate web frontend did not become ready');
  browser = await chromium.launch({ headless: true });
  browserPage = await browser.newPage({ viewport: { width: 1440, height: 1000 }, reducedMotion: 'reduce' });
  browserPage.setDefaultTimeout(60000);
  await browserPage.addInitScript(() => {
    const send = window.fetch;
    (window as any).feedReviewRequests = [];
    window.fetch = Object.assign(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = input instanceof Request ? input.url : String(input);
      if (url.includes('/api/main/v1/feed')) (window as any).feedReviewRequests.push({ url, credentials: init?.credentials, method: init?.method ?? 'GET' });
      return send(input, init);
    }, { preconnect: send.preconnect });
  });
  await browserPage.route('**/api/main/v1/feed?**', async route => {
    const url = new URL(route.request().url());
    if (url.searchParams.has('cursor') && !injected) {
      injected = true;
      network.push({ cursor: true, url: url.href, status: 409, injected: true });
      await route.fulfill({ status: 409, contentType: 'application/json', body: JSON.stringify({ code: 'cursor_conflict' }) });
      return;
    }
    if (delayFresh && !url.searchParams.has('cursor')) {
      delayFresh = false;
      const gate = new Promise<void>(resolve => { release = resolve; });
      const response = await route.fetch({ timeout: 60000 });
      await gate;
      network.push({ cursor: false, url: url.href, status: response.status(), retainedResponse: true });
      writeFileSync(`${evidence}/live-recovery-first-page.json`, await response.body());
      await route.fulfill({ response });
      return;
    }
    const response = await route.fetch({ timeout: 60000 });
    network.push({ cursor: url.searchParams.has('cursor'), url: url.href, status: response.status(), retainedResponse: true });
    if (response.ok()) writeFileSync(`${evidence}/live-browser-page-${network.length}.json`, await response.body());
    await route.fulfill({ response });
  });
}, 180000);

afterAll(async () => {
  release(); save();
  await browserPage?.unrouteAll({ behavior: 'wait' });
  await browser?.close();
  if (server?.pid) { try { process.kill(-server.pid, 'SIGTERM'); } catch {} }
});

test('live anonymous feed recovers once from an injected cursor 409 and retains keyboard focus', async () => {
  await browserPage.goto(`${origin}/en?lang=en`, { waitUntil: 'domcontentloaded', timeout: 120000 });
  const alert = browserPage.getByRole('alert').filter({ hasText: 'The feed changed while you were reading' });
  await alert.waitFor();
  const beforeUrl = browserPage.url();
  const refresh = alert.getByRole('button', { name: 'Refresh', exact: true });
  await refresh.focus();
  delayFresh = true;
  await browserPage.keyboard.press('Enter');
  await browserPage.getByText('Refreshing posts…', { exact: true }).waitFor();
  await browserPage.screenshot({ path: `${evidence}/live-focus-confirmation-pending-1440.png` });
  const pendingFocus = await browserPage.evaluate(() => document.activeElement?.tagName);
  release();
  await browserPage.waitForFunction(() => document.querySelectorAll('[data-feed-item]').length >= 6, { timeout: 60000 });
  await browserPage.getByRole('feed').getByRole('article').last().scrollIntoViewIfNeeded();
  await browserPage.waitForTimeout(1000);
  const count = await browserPage.locator('[data-feed-item]').count();
  const ids = await browserPage.locator('[data-feed-item]').evaluateAll(elements => elements.map(element => element.getAttribute('data-feed-item')));
  const requests = await browserPage.evaluate(() => (window as any).feedReviewRequests);
  const focus = await browserPage.evaluate(() => ({ tag: document.activeElement?.tagName, text: document.activeElement?.textContent?.slice(0, 100) }));
  await browserPage.screenshot({ path: `${evidence}/live-focus-confirmation-complete-1440.png` });
  await browserPage.keyboard.press('Tab');
  const nextTab = await browserPage.evaluate(() => ({ tag: document.activeElement?.tagName, text: document.activeElement?.textContent?.slice(0, 100), href: document.activeElement?.getAttribute('href') }));
  observations.push({ nextTab, case: 'real anonymous one-409 recovery', beforeUrl, afterUrl: browserPage.url(), pendingFocus, focus,
    count, uniqueIds: new Set(ids).size, ids, requests, remainingAlerts: await alert.count() }); save();
  expect(injected).toBe(true);
  expect(count).toBeGreaterThanOrEqual(6);
  expect(new Set(ids).size).toBe(count);
  expect(await alert.count()).toBe(0);
  expect(browserPage.url()).toBe(beforeUrl);
  expect(requests.every((request: any) => request.credentials === 'omit' && !new URL(request.url, origin).searchParams.has('actingSubject'))).toBe(true);
  expect(network.filter(request => !request.injected).every(request => request.status === 200)).toBe(true);
  expect(focus.tag).not.toBe('BODY');
}, 180000);
